export const BODY = {"level-2":{"id":"level-2","kind":"level","level":2,"src":"level:2","title":"Level 2 · Tens and Tables","body":"Bigger sums in columns, rounding to ten, the two, five and ten times tables, fractions of an amount, change, and the language of chance.","route":"#/atlas","cta":"See the road"},"land-l2-addsub":{"id":"land-l2-addsub","kind":"land","level":2,"src":"land:l2-addsub","title":"Column sums — in The Ten Gardens","body":"6 stops on this stretch of the road: Make ten first · Near doubles · Adding nine · Tens, then ones · Column addition · Column subtraction.","art":"art/w-gardens.webp","route":"#/world/gardens","cta":"Visit Gardens"},"land-l2-muldiv":{"id":"land-l2-muldiv","kind":"land","level":2,"src":"land:l2-muldiv","title":"Doubles, fives and halves — in The Times Market","body":"3 stops on this stretch of the road: Double, double, double · Times five is half of times ten · A fraction of an amount.","art":"art/w-market.webp","route":"#/world/market","cta":"Visit Market"},"land-l2-money":{"id":"land-l2-money","kind":"land","level":2,"src":"land:l2-money","title":"Change and the clock — in Coin Street","body":"4 stops on this stretch of the road: The fewest coins · What is left? · Reading the clock · Giving change.","art":"art/w-coinstreet.webp","route":"#/world/coinstreet","cta":"Visit Coins"},"hook-make-ten-hook":{"id":"hook-make-ten-hook","kind":"hook","src":"stop:make-ten#hook","title":"Can you? — Make ten first","body":"8 + 5 — can you do it without counting on?","cta":"Find out how","level":2,"route":"#/stop/make-ten"},"worked-make-ten-worked0":{"id":"worked-make-ten-worked0","kind":"worked","src":"stop:make-ten#worked0","title":"Worked out — Make ten first: Make ten","body":"8 + 5: How many does 8 need to make 10? → 2 · Take that from 5. What is left? → 3 · 10 + 3 → 13","cta":"Watch it step by step","level":2,"route":"#/stop/make-ten"},"worked-make-ten-worked1":{"id":"worked-make-ten-worked1","kind":"worked","src":"stop:make-ten#worked1","title":"Worked out — Make ten first: Make the next ten","body":"47 + 6: How many does 47 need to make 50? → 3 · Take that from 6. What is left? → 3 · 50 + 3 → 53","cta":"Watch it step by step","level":2,"route":"#/stop/make-ten"},"why-make-ten-why2":{"id":"why-make-ten-why2","kind":"why","src":"stop:make-ten#why2","title":"Why “Make ten first” works","body":"Bigger numbers make the NEXT ten the same way. 47 + 6: 47 needs 3 to make 50, and the 6 has 3 left over, so 53.","cta":"See why","level":2,"route":"#/stop/make-ten"},"moment-make-ten-beat4":{"id":"moment-make-ten-beat4","kind":"moment","src":"story:make-ten#beat4","badge":{"id":"story","label":"A story"},"title":"Pip's marbles — on the notepad","body":"Nova: And how many of my five are still in my hand? 5 − 2 = 3","cta":"Read the story","level":2,"route":"#/stop/make-ten"},"try-make-ten-L2":{"id":"try-make-ten-L2","kind":"try","level":2,"src":"try:make-ten@2/2#0","title":"Make ten first — your turn","route":"#/stop/make-ten","cta":"Practise this stop","play":{"q":"8 + 3 = ?","opts":["11","2","1"],"after":"Give the big number enough to make 10, then add what is left."}},"hook-near-doubles-hook":{"id":"hook-near-doubles-hook","kind":"hook","src":"stop:near-doubles#hook","title":"Can you? — Near doubles","body":"7 + 8 — two numbers next to each other.","cta":"Find out how","level":2,"route":"#/stop/near-doubles"},"why-near-doubles-why1":{"id":"why-near-doubles-why1","kind":"why","src":"stop:near-doubles#why1","title":"Why “Near doubles” works","body":"8 is just 7 and one more, so 7 + 8 is 7 + 7, and one more.","cta":"See why","level":2,"route":"#/stop/near-doubles"},"moment-near-doubles-beat4":{"id":"moment-near-doubles-beat4","kind":"moment","src":"story:near-doubles#beat4","badge":{"id":"story","label":"A story"},"title":"Two plates of sweets — on the notepad","body":"Suki: So the answer is one more than fourteen. 14 + 1 = 15","cta":"Read the story","level":2,"route":"#/stop/near-doubles"},"try-near-doubles-L2":{"id":"try-near-doubles-L2","kind":"try","level":2,"src":"try:near-doubles@2/2#0","title":"Near doubles — your turn","route":"#/stop/near-doubles","cta":"Practise this stop","play":{"q":"8 + 9 = ?","opts":["17","16","18"],"after":"Double the smaller one, then add one more."}},"hook-plus-nine-hook":{"id":"hook-plus-nine-hook","kind":"hook","src":"stop:plus-nine#hook","title":"Can you? — Adding nine","body":"34 + 9 — nine is almost ten.","cta":"Find out how","level":2,"route":"#/stop/plus-nine"},"worked-plus-nine-worked0":{"id":"worked-plus-nine-worked0","kind":"worked","src":"stop:plus-nine#worked0","title":"Worked out — Adding nine: Adding 9","body":"34 + 9: Add 10 instead → 44 · Take one away → 43","cta":"Watch it step by step","level":2,"route":"#/stop/plus-nine"},"worked-plus-nine-worked1":{"id":"worked-plus-nine-worked1","kind":"worked","src":"stop:plus-nine#worked1","title":"Worked out — Adding nine: Adding 19 or 29","body":"156 + 29: Add 30 instead → 186 · Take one away → 185","cta":"Watch it step by step","level":2,"route":"#/stop/plus-nine"},"worked-plus-nine-worked2":{"id":"worked-plus-nine-worked2","kind":"worked","src":"stop:plus-nine#worked2","title":"Worked out — Adding nine: Adding 99","body":"245 + 99: Add 100 instead → 345 · Take one away → 344","cta":"Watch it step by step","level":2,"route":"#/stop/plus-nine"},"why-plus-nine-why2":{"id":"why-plus-nine-why2","kind":"why","src":"stop:plus-nine#why2","title":"Why “Adding nine” works","body":"It is not only nine. 19 is one less than 20, 29 one less than 30, and 99 one less than 100. Add the round number, then take one away.","cta":"See why","level":2,"route":"#/stop/plus-nine"},"moment-plus-nine-beat4":{"id":"moment-plus-nine-beat4","kind":"moment","src":"story:plus-nine#beat4","badge":{"id":"story","label":"A story"},"title":"The bus stop — on the notepad","body":"Nova: So take the extra one back off. 44 − 1 = 43","cta":"Read the story","level":2,"route":"#/stop/plus-nine"},"try-plus-nine-L2":{"id":"try-plus-nine-L2","kind":"try","level":2,"src":"try:plus-nine@2/2#0","title":"Adding nine — your turn","route":"#/stop/plus-nine","cta":"Practise this stop","play":{"q":"26 + 9 = ?","opts":["35","36","34"],"after":"Add ten instead, then take one away."}},"hook-tens-then-ones-hook":{"id":"hook-tens-then-ones-hook","kind":"hook","src":"stop:tens-then-ones#hook","title":"Can you? — Tens, then ones","body":"47 + 36 — two two-digit numbers, no paper.","cta":"Find out how","level":2,"route":"#/stop/tens-then-ones"},"worked-tens-then-ones-worked0":{"id":"worked-tens-then-ones-worked0","kind":"worked","src":"stop:tens-then-ones#worked0","title":"Worked out — Tens, then ones: The ones stay small","body":"42 + 35: 40 + 30 → 70 · 2 + 5 → 7 · 70 + 7 → 77","cta":"Watch it step by step","level":2,"route":"#/stop/tens-then-ones"},"worked-tens-then-ones-worked1":{"id":"worked-tens-then-ones-worked1","kind":"worked","src":"stop:tens-then-ones#worked1","title":"Worked out — Tens, then ones: The ones make a new ten","body":"47 + 36: 40 + 30 → 70 · 7 + 6 → 13 · 70 + 13 → 83","cta":"Watch it step by step","level":2,"route":"#/stop/tens-then-ones"},"why-tens-then-ones-why2":{"id":"why-tens-then-ones-why2","kind":"why","src":"stop:tens-then-ones#why2","title":"Why “Tens, then ones” works","body":"Sometimes the ones make ten or more: 7 + 6 is 13. That is fine — 13 is one more ten and 3 ones, so 70 + 13 is 83.","cta":"See why","level":2,"route":"#/stop/tens-then-ones"},"moment-tens-then-ones-beat3":{"id":"moment-tens-then-ones-beat3","kind":"moment","src":"story:tens-then-ones#beat3","badge":{"id":"story","label":"A story"},"title":"The cricket score — on the notepad","body":"Dax: Then the ones. 7 + 6 = 13","cta":"Read the story","level":2,"route":"#/stop/tens-then-ones"},"try-tens-then-ones-L2":{"id":"try-tens-then-ones-L2","kind":"try","level":2,"src":"try:tens-then-ones@2/2#0","title":"Tens, then ones — your turn","route":"#/stop/tens-then-ones","cta":"Practise this stop","play":{"q":"46 + 26 = ?","opts":["72","60","12"],"after":"Add the tens, add the ones, then put them together."}},"trick-double-double-idea":{"id":"trick-double-double-idea","kind":"trick","src":"stop:double-double#idea","title":"Double, double, double","body":"Times 4 is double twice. Times 8 is double three times. 4 is 2 × 2, so multiplying by 4 is multiplying by 2 and then by 2 again.","cta":"Learn the trick","level":2,"route":"#/stop/double-double"},"story-double-double-open":{"id":"story-double-double-open","kind":"story","src":"story:double-double#open","badge":{"id":"story","label":"A story"},"title":"The egg boxes","body":"Nova buys 7 boxes of eggs at the market. Each box holds 8. — with Nova and Pip.","art":"art/s-market.webp","cta":"Read the story","level":2,"route":"#/stop/double-double"},"hook-double-double-hook":{"id":"hook-double-double-hook","kind":"hook","src":"stop:double-double#hook","title":"Can you? — Double, double, double","body":"7 × 8 — the one everybody forgets.","cta":"Find out how","level":2,"route":"#/stop/double-double"},"idea-double-double-case0":{"id":"idea-double-double-case0","kind":"idea","src":"stop:double-double#case0","title":"Double, double, double: Times 4: double twice","body":"Four is two twos, so two doublings do it.","cta":"See it worked","level":2,"route":"#/stop/double-double"},"worked-double-double-worked0":{"id":"worked-double-double-worked0","kind":"worked","src":"stop:double-double#worked0","title":"Worked out — Double, double, double: Times 4: double twice","body":"6 × 4: Double 6 → 12 · Double again → 24","cta":"Watch it step by step","level":2,"route":"#/stop/double-double"},"idea-double-double-case1":{"id":"idea-double-double-case1","kind":"idea","src":"stop:double-double#case1","title":"Double, double, double: Times 8: double 3 times","body":"Eight is two times two times two — one more doubling than times 4. Count your doublings: three.","cta":"See it worked","level":2,"route":"#/stop/double-double"},"worked-double-double-worked1":{"id":"worked-double-double-worked1","kind":"worked","src":"stop:double-double#worked1","title":"Worked out — Double, double, double: Times 8: double 3 times","body":"7 × 8: Double 7 → 14 · Double again → 28 · Double again → 56","cta":"Watch it step by step","level":2,"route":"#/stop/double-double"},"why-double-double-why1":{"id":"why-double-double-why1","kind":"why","src":"stop:double-double#why1","title":"Why “Double, double, double” works","body":"8 is 2 × 2 × 2. So 7 × 8 is 7, doubled, doubled, doubled: 14, 28, 56. You only ever need your two times table.","cta":"See why","level":2,"route":"#/stop/double-double"},"algebra-double-double-alg":{"id":"algebra-double-double-alg","kind":"algebra","src":"stop:double-double#alg","title":"The algebra behind “Double, double, double”","body":"n × 8 = ((n × 2) × 2) × 2","cta":"See why","level":2,"route":"#/stop/double-double"},"moment-double-double-beat3":{"id":"moment-double-double-beat3","kind":"moment","src":"story:double-double#beat3","badge":{"id":"story","label":"A story"},"title":"The egg boxes — on the notepad","body":"Pip: Double again? 14 × 2 = 28","cta":"Read the story","level":2,"route":"#/stop/double-double"},"moral-double-double-beat5":{"id":"moral-double-double-beat5","kind":"moral","src":"story:double-double#beat5","badge":{"id":"story","label":"A story"},"title":"Pip, in “The egg boxes”","body":"Fifty-six eggs. Double, double, double!","cta":"Read the story","level":2,"route":"#/stop/double-double"},"try-double-double-L2":{"id":"try-double-double-L2","kind":"try","level":2,"src":"try:double-double@2/1#0","title":"Double, double, double — your turn","route":"#/stop/double-double","cta":"Practise this stop","play":{"q":"3 × 8 = ?","opts":["24","6","12"],"after":"Times 4 is double twice. Times 8 is double three times."}},"trick-times-five-idea":{"id":"trick-times-five-idea","kind":"trick","src":"stop:times-five#idea","title":"Times five is half of times ten","body":"Times it by ten, then halve it. Five is half of ten. So five lots of anything is half of ten lots of it.","cta":"Learn the trick","level":2,"route":"#/stop/times-five"},"story-times-five-open":{"id":"story-times-five-open","kind":"story","src":"story:times-five#open","badge":{"id":"story","label":"A story"},"title":"The sticker stall","body":"Stickers cost 5 tokens each. Dax wants 14 of them. — with Dax and Suki.","art":"art/s-fair.webp","cta":"Read the story","level":2,"route":"#/stop/times-five"},"hook-times-five-hook":{"id":"hook-times-five-hook","kind":"hook","src":"stop:times-five#hook","title":"Can you? — Times five is half of times ten","body":"14 × 5 — try it without the five times table.","cta":"Find out how","level":2,"route":"#/stop/times-five"},"idea-times-five-case0":{"id":"idea-times-five-case0","kind":"idea","src":"stop:times-five#case0","title":"Times five is half of times ten: An even number","body":"Half of 140 is easy: half of 14 is 7, then put the 0 back. The answer ends in 0.","cta":"See it worked","level":2,"route":"#/stop/times-five"},"worked-times-five-worked0":{"id":"worked-times-five-worked0","kind":"worked","src":"stop:times-five#worked0","title":"Worked out — Times five is half of times ten: An even number","body":"14 × 5: 14 × 10 → 140 · Halve it → 70","cta":"Watch it step by step","level":2,"route":"#/stop/times-five"},"idea-times-five-case1":{"id":"idea-times-five-case1","kind":"idea","src":"stop:times-five#case1","title":"Times five is half of times ten: An odd number","body":"Half of 170 leaves an odd ten to split: half of 10 is 5. So the answer ends in 5.","cta":"See it worked","level":2,"route":"#/stop/times-five"},"worked-times-five-worked1":{"id":"worked-times-five-worked1","kind":"worked","src":"stop:times-five#worked1","title":"Worked out — Times five is half of times ten: An odd number","body":"17 × 5: 17 × 10 → 170 · Halve it → 85","cta":"Watch it step by step","level":2,"route":"#/stop/times-five"},"why-times-five-why1":{"id":"why-times-five-why1","kind":"why","src":"stop:times-five#why1","title":"Why “Times five is half of times ten” works","body":"Times ten is easy, halving is easy, and together they do the hard thing.","cta":"See why","level":2,"route":"#/stop/times-five"},"why-times-five-why2":{"id":"why-times-five-why2","kind":"why","src":"stop:times-five#why2","title":"Why “Times five is half of times ten” works","body":"An even number halves neatly: 14 × 10 is 140, and half of 140 is 70. An odd number leaves a half ten: 17 × 10 is 170, which is 160 and 10, so half is 80 and 5 — 85. An odd number times five always ends in 5.","cta":"See why","level":2,"route":"#/stop/times-five"},"algebra-times-five-alg":{"id":"algebra-times-five-alg","kind":"algebra","src":"stop:times-five#alg","title":"The algebra behind “Times five is half of times ten”","body":"n × 5 = (n × 10) ÷ 2","cta":"See why","level":2,"route":"#/stop/times-five"},"moment-times-five-beat3":{"id":"moment-times-five-beat3","kind":"moment","src":"story:times-five#beat3","badge":{"id":"story","label":"A story"},"title":"The sticker stall — on the notepad","body":"Suki: Now halve it. 140 ÷ 2 = 70","cta":"Read the story","level":2,"route":"#/stop/times-five"},"moral-times-five-beat4":{"id":"moral-times-five-beat4","kind":"moral","src":"story:times-five#beat4","badge":{"id":"story","label":"A story"},"title":"Dax, in “The sticker stall”","body":"Seventy tokens. Times ten, then halve!","cta":"Read the story","level":2,"route":"#/stop/times-five"},"try-times-five-L2":{"id":"try-times-five-L2","kind":"try","level":2,"src":"try:times-five@2/1#0","title":"Times five is half of times ten — your turn","route":"#/stop/times-five","cta":"Practise this stop","play":{"q":"24 × 5 = ?","opts":["120","240","121"],"after":"Times it by ten, then halve it."}},"hook-place-value-hook":{"id":"hook-place-value-hook","kind":"hook","src":"stop:place-value#hook","title":"Can you? — What is a digit worth?","body":"In 4,372 there is a 3. Is it worth three?","cta":"Find out how","level":2,"route":"#/stop/place-value"},"worked-place-value-worked0":{"id":"worked-place-value-worked0","kind":"worked","src":"stop:place-value#worked0","title":"Worked out — What is a digit worth?: What is a digit worth?","body":"In 4,372, what is the 3 worth?: Count the places to the 3, from the right — the ones are place 1 → 3 · That is the hundreds place. One of those is worth → 100 · 3 × 100 → 300","cta":"Watch it step by step","level":2,"route":"#/stop/place-value"},"worked-place-value-worked1":{"id":"worked-place-value-worked1","kind":"worked","src":"stop:place-value#worked1","title":"Worked out — What is a digit worth?: The missing part","body":"5,847 = 5000 + ? + 40 + 7: Add up the parts you can see → 5047 · 5847 − 5047 → 800","cta":"Watch it step by step","level":2,"route":"#/stop/place-value"},"why-place-value-why2":{"id":"why-place-value-why2","kind":"why","src":"stop:place-value#why2","title":"Why “What is a digit worth?” works","body":"That is why a number can be pulled apart into its places: 4,372 is 4000 + 300 + 70 + 2. Every written method in this Library — carrying, exchanging, long multiplication — is this one idea at work.","cta":"See why","level":2,"route":"#/stop/place-value"},"moment-place-value-beat3":{"id":"moment-place-value-beat3","kind":"moment","src":"story:place-value#beat3","badge":{"id":"story","label":"A story"},"title":"The shelf mark — on the notepad","body":"Rafi: That 3 sits in the hundreds place. It is not three — it is three hundreds. 3 × 100 = 300","cta":"Read the story","level":2,"route":"#/stop/place-value"},"try-place-value-L2":{"id":"try-place-value-L2","kind":"try","level":2,"src":"try:place-value@2/2#0","title":"What is a digit worth? — your turn","route":"#/stop/place-value","cta":"Practise this stop","play":{"q":"In 731, what is the 7 worth?","opts":["700","3","100"],"after":"Count the places from the right — ones, tens, hundreds, thousands — and the place tells you what the digit is worth."}},"hook-compare-big-hook":{"id":"hook-compare-big-hook","kind":"hook","src":"stop:compare-big#hook","title":"Can you? — Bigger or smaller?","body":"98,765 or 102,345 — which is bigger? The first has bigger digits…","cta":"Find out how","level":2,"route":"#/stop/compare-big"},"idea-compare-big-case1":{"id":"idea-compare-big-case1","kind":"idea","src":"stop:compare-big#case1","title":"Bigger or smaller?: More digits wins","body":"Count the digits before you look at them. Five digits is smaller than six, however big they are — so this time the sign is <.","cta":"See it worked","level":2,"route":"#/stop/compare-big"},"why-compare-big-why1":{"id":"why-compare-big-why1","kind":"why","src":"stop:compare-big#why1","title":"Why “Bigger or smaller?” works","body":"When two numbers have the same number of digits, the leftmost digit is worth the most. 4,372 and 4,327 both have 4 thousands and 3 hundreds; the tens are the first place they differ, and 7 tens beats 2 tens. Nothing to the right can catch up, because even 9 ones is less than one more ten.","cta":"See why","level":2,"route":"#/stop/compare-big"},"algebra-compare-big-alg":{"id":"algebra-compare-big-alg","kind":"algebra","src":"stop:compare-big#alg","title":"The algebra behind “Bigger or smaller?”","body":"compare digit counts; if equal, the first place where aₖ ≠ bₖ decides","cta":"See why","level":2,"route":"#/stop/compare-big"},"trick-round-nearest-idea":{"id":"trick-round-nearest-idea","kind":"trick","src":"stop:round-nearest#idea","title":"Rounding","body":"Find the two round numbers either side, find halfway, and see which side of halfway you are on. Rounding asks: which round number is closest? 4,372 sits between 4,300 and 4,400 on the number line. Halfway between them is 4,350, and 4,372 is past halfway, so it is closer to 4,400.","cta":"Learn the trick","level":2,"route":"#/stop/round-nearest"},"story-round-nearest-open":{"id":"story-round-nearest-open","kind":"story","src":"story:round-nearest#open","badge":{"id":"story","label":"A story"},"title":"About how many?","body":"The library has 4,372 books. The poster outside should give a round number, to the nearest hundred. — with Nova and Dax.","art":"art/s-library.webp","cta":"Read the story","level":2,"route":"#/stop/round-nearest"},"hook-round-nearest-hook":{"id":"hook-round-nearest-hook","kind":"hook","src":"stop:round-nearest#hook","title":"Can you? — Rounding","body":"Round 4,372 to the nearest hundred — up to 4,400 or down to 4,300?","cta":"Find out how","level":2,"route":"#/stop/round-nearest"},"idea-round-nearest-case0":{"id":"idea-round-nearest-case0","kind":"idea","src":"stop:round-nearest#case0","title":"Rounding: Past halfway: round up","body":"To the nearest hundred, look at the tens digit. 7 tens is past the halfway 5 tens, so up it goes.","cta":"See it worked","level":2,"route":"#/stop/round-nearest"},"worked-round-nearest-worked0":{"id":"worked-round-nearest-worked0","kind":"worked","src":"stop:round-nearest#worked0","title":"Worked out — Rounding: Past halfway: round up","body":"Round 4,372 to the nearest 100: The multiple of 100 just below 4,372 → 4300 · The one just above → 4400 · Halfway between them → 4350 · Is 4,372 below halfway (round down), or at or past it (round up)? → 4400","cta":"Watch it step by step","level":2,"route":"#/stop/round-nearest"},"idea-round-nearest-case1":{"id":"idea-round-nearest-case1","kind":"idea","src":"stop:round-nearest#case1","title":"Rounding: Below halfway: round down","body":"To the nearest ten, look at the ones digit. 3 is below halfway, so it rounds DOWN — the tens digit stays as it is.","cta":"See it worked","level":2,"route":"#/stop/round-nearest"},"worked-round-nearest-worked1":{"id":"worked-round-nearest-worked1","kind":"worked","src":"stop:round-nearest#worked1","title":"Worked out — Rounding: Below halfway: round down","body":"Round 63 to the nearest 10: The multiple of 10 just below 63 → 60 · The one just above → 70 · Halfway between them → 65 · Is 63 below halfway (round down), or at or past it (round up)? → 60","cta":"Watch it step by step","level":2,"route":"#/stop/round-nearest"},"idea-round-nearest-case2":{"id":"idea-round-nearest-case2","kind":"idea","src":"stop:round-nearest#case2","title":"Rounding: Exactly halfway","body":"To the nearest thousand, look at the hundreds. 2,500 is exactly halfway — equally close to both — and the agreed rule is: halfway rounds up.","cta":"See it worked","level":2,"route":"#/stop/round-nearest"},"worked-round-nearest-worked2":{"id":"worked-round-nearest-worked2","kind":"worked","src":"stop:round-nearest#worked2","title":"Worked out — Rounding: Exactly halfway","body":"Round 2,500 to the nearest 1,000: The multiple of 1000 just below 2,500 → 2000 · The one just above → 3000 · Halfway between them → 2500 · Is 2,500 below halfway (round down), or at or past it (round up)? → 3000","cta":"Watch it step by step","level":2,"route":"#/stop/round-nearest"},"why-round-nearest-why1":{"id":"why-round-nearest-why1","kind":"why","src":"stop:round-nearest#why1","title":"Why “Rounding” works","body":"You only need to look at one digit — the one just to the right of the place you are rounding to. For hundreds, that is the tens digit: 7 tens is past the halfway mark of 5 tens, so round up. Everything further right is too small to change the decision.","cta":"See why","level":2,"route":"#/stop/round-nearest"},"why-round-nearest-why2":{"id":"why-round-nearest-why2","kind":"why","src":"stop:round-nearest#why2","title":"Why “Rounding” works","body":"Exactly halfway (like 4,350) is equally close to both. Mathematicians agreed a rule so that everybody gets the same answer: halfway rounds up.","cta":"See why","level":2,"route":"#/stop/round-nearest"},"algebra-round-nearest-alg":{"id":"algebra-round-nearest-alg","kind":"algebra","src":"stop:round-nearest#alg","title":"The algebra behind “Rounding”","body":"round(n, to) = to × ⌊n ÷ to + ½⌋","cta":"See why","level":2,"route":"#/stop/round-nearest"},"moment-round-nearest-beat3":{"id":"moment-round-nearest-beat3","kind":"moment","src":"story:round-nearest#beat3","badge":{"id":"story","label":"A story"},"title":"About how many? — on the notepad","body":"Nova: Halfway between them is 4,350. (4300 + 4400) ÷ 2 = 4350","cta":"Read the story","level":2,"route":"#/stop/round-nearest"},"moral-round-nearest-beat5":{"id":"moral-round-nearest-beat5","kind":"moral","src":"story:round-nearest#beat5","badge":{"id":"story","label":"A story"},"title":"Nova, in “About how many?”","body":"So it rounds up. The poster says about 4,400 books.","cta":"Read the story","level":2,"route":"#/stop/round-nearest"},"try-round-nearest-L2":{"id":"try-round-nearest-L2","kind":"try","level":2,"src":"try:round-nearest@2/1#0","title":"Rounding — your turn","route":"#/stop/round-nearest","cta":"Practise this stop","play":{"q":"Round 95 to the nearest 10 = ?","opts":["100","90","95"],"after":"Find the two round numbers either side, find halfway, and see which side of halfway you are on."}},"trick-column-add-idea":{"id":"trick-column-add-idea","kind":"trick","src":"stop:column-add#idea","title":"Column addition","body":"Line the numbers up by place. Add each column from the right; when a column makes ten or more, carry the ten to the next column. Lining up the digits puts ones with ones, tens with tens, hundreds with hundreds. You can only add things of the same kind — 8 ones and 7 ones make 15 ones.","cta":"Learn the trick","level":2,"route":"#/stop/column-add"},"story-column-add-open":{"id":"story-column-add-open","kind":"story","src":"story:column-add#open","badge":{"id":"story","label":"A story"},"title":"The book sale","body":"On Saturday the book sale raised 368 rupees. On Sunday it raised 457. — with Rafi and Pip.","art":"art/s-library.webp","cta":"Read the story","level":2,"route":"#/stop/column-add"},"idea-column-add-case0":{"id":"idea-column-add-case0","kind":"idea","src":"stop:column-add#case0","title":"Column addition: One carry","body":"Only the ones make ten or more. Their ten goes to the top of the tens column and is added in with the tens.","cta":"See it worked","level":2,"route":"#/stop/column-add"},"idea-column-add-case1":{"id":"idea-column-add-case1","kind":"idea","src":"stop:column-add#case1","title":"Column addition: Carry after carry","body":"The carried one can make the next column reach ten too — then that column carries as well. Always add the carry in.","cta":"See it worked","level":2,"route":"#/stop/column-add"},"idea-column-add-case2":{"id":"idea-column-add-case2","kind":"idea","src":"stop:column-add#case2","title":"Column addition: A carry makes a new place","body":"The last column carries too, and there is nothing to its left. The carried one starts a new place of its own at the front.","cta":"See it worked","level":2,"route":"#/stop/column-add"},"why-column-add-why1":{"id":"why-column-add-why1","kind":"why","src":"stop:column-add#why1","title":"Why “Column addition” works","body":"But a column can only hold one digit. 15 ones is 1 ten and 5 ones, so the 5 stays and the ten moves to the tens column, where it belongs. That is all carrying is: ten of one place swapped for one of the next.","cta":"See why","level":2,"route":"#/stop/column-add"},"algebra-column-add-alg":{"id":"algebra-column-add-alg","kind":"algebra","src":"stop:column-add#alg","title":"The algebra behind “Column addition”","body":"column k: aₖ + bₖ + carry = 10 × (next carry) + digitₖ","cta":"See why","level":2,"route":"#/stop/column-add"},"moral-column-add-beat5":{"id":"moral-column-add-beat5","kind":"moral","src":"story:column-add#beat5","badge":{"id":"story","label":"A story"},"title":"Rafi, in “The book sale”","body":"Read it off: 8, 2, 5.","cta":"Read the story","level":2,"route":"#/stop/column-add"},"try-column-add-L2":{"id":"try-column-add-L2","kind":"try","level":2,"src":"try:column-add@2/1#0","title":"Column addition — your turn","route":"#/stop/column-add","cta":"Practise this stop","play":{"q":"71 + 59 = ?","opts":["130","10","13"],"after":"Line the numbers up by place. Add each column from the right; when a column makes ten or more, carry the ten to the next column."}},"trick-column-sub-idea":{"id":"trick-column-sub-idea","kind":"trick","src":"stop:column-sub#idea","title":"Column subtraction","body":"Line up by place and subtract from the right. When the top digit is too small, exchange one from the next column: it arrives as ten. You cannot take 8 ones from 2 ones. But the number has more in it than those 2 ones: it has tens next door. Break one ten open and it becomes ten ones, so now there are 12 ones, and 12 − 8 is fine.","cta":"Learn the trick","level":2,"route":"#/stop/column-sub"},"story-column-sub-open":{"id":"story-column-sub-open","kind":"story","src":"story:column-sub#open","badge":{"id":"story","label":"A story"},"title":"Books still out","body":"The library lent 532 books this month. 178 have come back. How many are still out? — with Suki and Dax.","art":"art/s-library.webp","cta":"Read the story","level":2,"route":"#/stop/column-sub"},"idea-column-sub-case0":{"id":"idea-column-sub-case0","kind":"idea","src":"stop:column-sub#case0","title":"Column subtraction: One exchange","body":"Only the ones are too small. One ten from next door becomes ten ones, and the tens column has one fewer to give.","cta":"See it worked","level":2,"route":"#/stop/column-sub"},"idea-column-sub-case1":{"id":"idea-column-sub-case1","kind":"idea","src":"stop:column-sub#case1","title":"Column subtraction: Exchange after exchange","body":"After lending, the tens are too small as well — so they exchange from the hundreds. Remember each column has one fewer after it lends.","cta":"See it worked","level":2,"route":"#/stop/column-sub"},"idea-column-sub-case2":{"id":"idea-column-sub-case2","kind":"idea","src":"stop:column-sub#case2","title":"Column subtraction: Across a zero","body":"The next column is a 0 with nothing to lend, so it exchanges from ITS neighbour first. That is why the 0s turn into 9s.","cta":"See it worked","level":2,"route":"#/stop/column-sub"},"why-column-sub-why1":{"id":"why-column-sub-why1","kind":"why","src":"stop:column-sub#why1","title":"Why “Column subtraction” works","body":"Nothing has been added or lost. 532 is 5 hundreds, 3 tens and 2 ones, and it is also 5 hundreds, 2 tens and 12 ones — the same amount, packed differently. The tens column just has one fewer to give.","cta":"See why","level":2,"route":"#/stop/column-sub"},"algebra-column-sub-alg":{"id":"algebra-column-sub-alg","kind":"algebra","src":"stop:column-sub#alg","title":"The algebra behind “Column subtraction”","body":"column k: if aₖ − borrow < bₖ, use aₖ − borrow + 10 and borrow 1 from column k + 1","cta":"See why","level":2,"route":"#/stop/column-sub"},"moral-column-sub-beat5":{"id":"moral-column-sub-beat5","kind":"moral","src":"story:column-sub#beat5","badge":{"id":"story","label":"A story"},"title":"Suki, in “Books still out”","body":"354 books still out. Nothing was lost — only packed differently.","cta":"Read the story","level":2,"route":"#/stop/column-sub"},"try-column-sub-L2":{"id":"try-column-sub-L2","kind":"try","level":2,"src":"try:column-sub@2/1#0","title":"Column subtraction — your turn","route":"#/stop/column-sub","cta":"Practise this stop","play":{"q":"81 − 29 = ?","opts":["52","2","5"],"after":"Line up by place and subtract from the right. When the top digit is too small, exchange one from the next column: it arrives as ten."}},"hook-read-the-clock-hook":{"id":"hook-read-the-clock-hook","kind":"hook","src":"stop:read-the-clock#hook","title":"Can you? — Reading the clock","body":"The long hand points at the 9 and the short hand is nearly at the 4. What time is it?","cta":"Find out how","level":2,"route":"#/stop/read-the-clock"},"idea-read-the-clock-case1":{"id":"idea-read-the-clock-case1","kind":"idea","src":"stop:read-the-clock#case1","title":"Reading the clock: Minutes to the next hour","body":"A full turn of the long hand is 60 minutes, so the minutes still to go are 60 take away the minutes already past.","cta":"See it worked","level":2,"route":"#/stop/read-the-clock"},"why-read-the-clock-why1":{"id":"why-read-the-clock-why1","kind":"why","src":"stop:read-the-clock#why1","title":"Why “Reading the clock” works","body":"The short hand goes round once every 12 hours, so it creeps slowly from one number to the next as the hour passes. At 3:45 it is three-quarters of the way from the 3 to the 4 — it has not reached the 4 yet, so the hour is still 3.","cta":"See why","level":2,"route":"#/stop/read-the-clock"},"algebra-read-the-clock-alg":{"id":"algebra-read-the-clock-alg","kind":"algebra","src":"stop:read-the-clock#alg","title":"The algebra behind “Reading the clock”","body":"minutes = 5 × (number the long hand points to)","cta":"See why","level":2,"route":"#/stop/read-the-clock"},"moral-read-the-clock-beat5":{"id":"moral-read-the-clock-beat5","kind":"moral","src":"story:read-the-clock#beat5","badge":{"id":"story","label":"A story"},"title":"Pip, in “The tower clock”","body":"So it is 3:45 — and 15 minutes until four.","cta":"Read the story","level":2,"route":"#/stop/read-the-clock"},"trick-giving-change-idea":{"id":"trick-giving-change-idea","kind":"trick","src":"stop:giving-change#idea","title":"Giving change","body":"Count UP from the price to what you paid — to the next ten first, then on. The jumps are the change. Change is the gap between the price and what you handed over. A gap can be measured from either end, and counting up from the price is how shopkeepers have always done it: 37… 40… 50, and they hand you coins as they count.","cta":"Learn the trick","level":2,"route":"#/stop/giving-change"},"story-giving-change-open":{"id":"story-giving-change-open","kind":"story","src":"story:giving-change#open","badge":{"id":"story","label":"A story"},"title":"The comic stall","body":"At the market, Dax buys a comic for 37 coins. He pays with 50 coins. — with Ines and Dax.","art":"art/s-market.webp","cta":"Read the story","level":2,"route":"#/stop/giving-change"},"worked-giving-change-worked0":{"id":"worked-giving-change-worked0","kind":"worked","src":"stop:giving-change#worked0","title":"Worked out — Giving change: Buying one thing","body":"A comic costs 37 coins. You pay with 50 coins. How many coins do you get back?: 37 up to 40 → 3 · 40 up to 50 → 10 · Add the jumps: your change → 13","cta":"Watch it step by step","level":2,"route":"#/stop/giving-change"},"why-giving-change-why1":{"id":"why-giving-change-why1","kind":"why","src":"stop:giving-change#why1","title":"Why “Giving change” works","body":"Jumping to the next ten first makes every jump easy. 37 up to 40 is 3, then 40 up to 50 is 10. 3 + 10 = 13. You never have to \"borrow\" the way you would in 50 − 37 written out.","cta":"See why","level":2,"route":"#/stop/giving-change"},"moment-giving-change-beat3":{"id":"moment-giving-change-beat3","kind":"moment","src":"story:giving-change#beat3","badge":{"id":"story","label":"A story"},"title":"The comic stall — on the notepad","body":"Dax: Then 40 up to 50. 50 − 40 = 10","cta":"Read the story","level":2,"route":"#/stop/giving-change"},"try-giving-change-L2":{"id":"try-giving-change-L2","kind":"try","level":2,"src":"try:giving-change@2/1#0","title":"Giving change — your turn","route":"#/stop/giving-change","cta":"Practise this stop","play":{"q":"A kite costs 9 coins. You pay with 10 coins. How many coins do you get back?","opts":["1","2","0"],"after":"Count UP from the price to what you paid — to the next ten first, then on. The jumps are the change."}},"hook-fraction-parts-hook":{"id":"hook-fraction-parts-hook","kind":"hook","src":"stop:fraction-parts#hook","title":"Can you? — Halves, quarters and thirds","body":"Half a pie, a quarter of a cake — what do those words really mean?","cta":"Find out how","level":2,"route":"#/stop/fraction-parts"},"algebra-fraction-parts-alg":{"id":"algebra-fraction-parts-alg","kind":"algebra","src":"stop:fraction-parts#alg","title":"The algebra behind “Halves, quarters and thirds”","body":"k shaded out of n equal parts = k/n","cta":"See why","level":2,"route":"#/stop/fraction-parts"},"trick-fraction-of-amount-idea":{"id":"trick-fraction-of-amount-idea","kind":"trick","src":"stop:fraction-of-amount#idea","title":"A fraction of an amount","body":"Divide by the bottom to find one share, then multiply by the top. 1/4 of 20 means: share 20 fairly between 4. Each share is 20 ÷ 4 = 5. The bottom number of a fraction is always a sharing — a division.","cta":"Learn the trick","level":2,"route":"#/stop/fraction-of-amount"},"story-fraction-of-amount-open":{"id":"story-fraction-of-amount-open","kind":"story","src":"story:fraction-of-amount#open","badge":{"id":"story","label":"A story"},"title":"Sharing the laddoos","body":"There are 20 laddoos on the tray. Pip is allowed to take three quarters of them to the party. — with Ines and Pip.","art":"art/s-kitchen.webp","cta":"Read the story","level":2,"route":"#/stop/fraction-of-amount"},"idea-fraction-of-amount-case0":{"id":"idea-fraction-of-amount-case0","kind":"idea","src":"stop:fraction-of-amount#case0","title":"A fraction of an amount: One share: 1/4 of","body":"With a 1 on top you only need one share, so dividing by the bottom is the whole job.","cta":"See it worked","level":2,"route":"#/stop/fraction-of-amount"},"idea-fraction-of-amount-case1":{"id":"idea-fraction-of-amount-case1","kind":"idea","src":"stop:fraction-of-amount#case1","title":"A fraction of an amount: Several shares: 3/4 of","body":"Find one share first by dividing, then take as many shares as the top number says.","cta":"See it worked","level":2,"route":"#/stop/fraction-of-amount"},"why-fraction-of-amount-why1":{"id":"why-fraction-of-amount-why1","kind":"why","src":"stop:fraction-of-amount#why1","title":"Why “A fraction of an amount” works","body":"3/4 is three of those shares. One share is 5, so three shares are 15. The top number just counts how many shares you take.","cta":"See why","level":2,"route":"#/stop/fraction-of-amount"},"algebra-fraction-of-amount-alg":{"id":"algebra-fraction-of-amount-alg","kind":"algebra","src":"stop:fraction-of-amount#alg","title":"The algebra behind “A fraction of an amount”","body":"(a/b) of n = (n ÷ b) × a","cta":"See why","level":2,"route":"#/stop/fraction-of-amount"},"moral-fraction-of-amount-beat5":{"id":"moral-fraction-of-amount-beat5","kind":"moral","src":"story:fraction-of-amount#beat5","badge":{"id":"story","label":"A story"},"title":"Pip, in “Sharing the laddoos”","body":"Fifteen laddoos. Divide by the bottom, times by the top!","cta":"Read the story","level":2,"route":"#/stop/fraction-of-amount"},"try-fraction-of-amount-L2":{"id":"try-fraction-of-amount-L2","kind":"try","level":2,"src":"try:fraction-of-amount@2/1#0","title":"A fraction of an amount — your turn","route":"#/stop/fraction-of-amount","cta":"Practise this stop","play":{"q":"1/4 of 20 = ?","opts":["5","4","6"],"after":"Divide by the bottom to find one share, then multiply by the top."}},"why-fewest-coins-why1":{"id":"why-fewest-coins-why1","kind":"why","src":"stop:fewest-coins#why1","title":"Why “The fewest coins” works","body":"For each part, take the biggest coin that fits, then the biggest that fits what is left. 30 is a 20 and a 10: two coins. 7 is a 5 and a 2: two coins. So 37 takes 4 coins.","cta":"See why","level":2,"route":"#/stop/fewest-coins"},"algebra-fewest-coins-alg":{"id":"algebra-fewest-coins-alg","kind":"algebra","src":"stop:fewest-coins#alg","title":"The algebra behind “The fewest coins”","body":"fewest(n) = fewest(tens of n, with 50, 20, 10) + fewest(ones of n, with 5, 2, 1)","cta":"See why","level":2,"route":"#/stop/fewest-coins"},"moral-fewest-coins-beat5":{"id":"moral-fewest-coins-beat5","kind":"moral","src":"story:fewest-coins#beat5","badge":{"id":"story","label":"A story"},"title":"Pip, in “The toy shop till”","body":"Four coins instead of thirty-seven. The shopkeeper will be pleased.","cta":"Read the story","level":2,"route":"#/stop/fewest-coins"},"hook-money-left-hook":{"id":"hook-money-left-hook","kind":"hook","src":"stop:money-left#hook","title":"Can you? — What is left?","body":"Nova has 40 coins to spend at the fair. She spends 12 on a ride and 9 on a snack. How many are left?","cta":"Find out how","level":2,"route":"#/stop/money-left"},"why-money-left-why2":{"id":"why-money-left-why2","kind":"why","src":"stop:money-left#why2","title":"Why “What is left?” works","body":"The bar shows it: the whole bar is the money at the start, the coloured pieces are what was spent, and the piece left over is what is still in the purse.","cta":"See why","level":2,"route":"#/stop/money-left"},"moral-money-left-beat5":{"id":"moral-money-left-beat5","kind":"moral","src":"story:money-left#beat5","badge":{"id":"story","label":"A story"},"title":"Nova, in “A day at the fair”","body":"19 coins left for the rest of the fair.","cta":"Read the story","level":2,"route":"#/stop/money-left"},"try-money-left-L2":{"id":"try-money-left-L2","kind":"try","level":2,"src":"try:money-left@2/2#0","title":"What is left? — your turn","route":"#/stop/money-left","cta":"Practise this stop","play":{"q":"Nova has 90 coins to spend at the fair and spends 28 on a ride and 16 on a snack. How many coins are left?","opts":["46","44","47"],"after":"Add up everything spent first, then take it away just once."}},"hook-sides-and-corners-hook":{"id":"hook-sides-and-corners-hook","kind":"hook","src":"stop:sides-and-corners#hook","title":"Can you? — Sides and corners","body":"A road sign has eight straight sides. What do you call a shape with six?","cta":"Find out how","level":2,"route":"#/stop/sides-and-corners"},"idea-sides-and-corners-case1":{"id":"idea-sides-and-corners-case1","kind":"idea","src":"stop:sides-and-corners#case1","title":"Sides and corners: Count the corners","body":"You do not need to count the corners at all: every side ends at a corner, so there are just as many corners as sides.","cta":"See it worked","level":2,"route":"#/stop/sides-and-corners"},"why-sides-and-corners-why1":{"id":"why-sides-and-corners-why1","kind":"why","src":"stop:sides-and-corners#why1","title":"Why “Sides and corners” works","body":"That is why a shape is named by one number. The start of each name is an old counting word: tri- means three (like a tricycle), penta- five, hexa- six, hepta- seven, octa- eight (like an octopus), nona- nine and deca- ten. A square is the special four-sided shape with equal sides and square corners.","cta":"See why","level":2,"route":"#/stop/sides-and-corners"},"algebra-sides-and-corners-alg":{"id":"algebra-sides-and-corners-alg","kind":"algebra","src":"stop:sides-and-corners#alg","title":"The algebra behind “Sides and corners”","body":"sides = corners = n","cta":"See why","level":2,"route":"#/stop/sides-and-corners"},"moral-sides-and-corners-beat6":{"id":"moral-sides-and-corners-beat6","kind":"moral","src":"story:sides-and-corners#beat6","badge":{"id":"story","label":"A story"},"title":"Mira, in “The shape walk”","body":"Eight sides — an octagon. Octa means eight, like an octopus.","cta":"Read the story","level":2,"route":"#/stop/sides-and-corners"},"hook-lines-of-symmetry-hook":{"id":"hook-lines-of-symmetry-hook","kind":"hook","src":"stop:lines-of-symmetry#hook","title":"Can you? — Lines of symmetry","body":"You can fold a square in half four different ways. How many ways can you fold a rectangle?","cta":"Find out how","level":2,"route":"#/stop/lines-of-symmetry"},"idea-lines-of-symmetry-case2":{"id":"idea-lines-of-symmetry-case2","kind":"idea","src":"stop:lines-of-symmetry#case2","title":"Lines of symmetry: Regular, even sides","body":"With an even number of equal sides, half the folds join opposite corners and half join the middles of opposite sides.","cta":"See it worked","level":2,"route":"#/stop/lines-of-symmetry"},"why-lines-of-symmetry-why1":{"id":"why-lines-of-symmetry-why1","kind":"why","src":"stop:lines-of-symmetry#why1","title":"Why “Lines of symmetry” works","body":"A regular shape (all sides and corners equal) with n sides has exactly n fold lines. With an odd number of sides, each fold runs from a corner to the middle of the opposite side. With an even number, half the folds join opposite corners and half join the middles of opposite sides.","cta":"See why","level":2,"route":"#/stop/lines-of-symmetry"},"moment-lines-of-symmetry-beat5":{"id":"moment-lines-of-symmetry-beat5","kind":"moment","src":"story:lines-of-symmetry#beat5","badge":{"id":"story","label":"A story"},"title":"Folding the kite paper — on the notepad","body":"Rafi: So only the two straight folds work: top to bottom, and side to side. 4 − 2 = 2","cta":"Read the story","level":2,"route":"#/stop/lines-of-symmetry"},"hook-pictogram-total-hook":{"id":"hook-pictogram-total-hook","kind":"hook","src":"stop:pictogram-total#hook","title":"Can you? — Reading a pictogram","body":"One star stands for 4 prizes. Half a star — how many is that?","cta":"Find out how","level":2,"route":"#/stop/pictogram-total"},"idea-pictogram-total-case2":{"id":"idea-pictogram-total-case2","kind":"idea","src":"stop:pictogram-total#case2","title":"Reading a pictogram: The whole chart","body":"Altogether means every row. Count all the whole stars, times by the key, then add the halves.","cta":"See it worked","level":2,"route":"#/stop/pictogram-total"},"algebra-pictogram-total-alg":{"id":"algebra-pictogram-total-alg","kind":"algebra","src":"stop:pictogram-total#alg","title":"The algebra behind “Reading a pictogram”","body":"total = (whole symbols × key) + (half symbols × key ÷ 2)","cta":"See why","level":2,"route":"#/stop/pictogram-total"},"hook-bar-compare-hook":{"id":"hook-bar-compare-hook","kind":"hook","src":"stop:bar-compare#hook","title":"Can you? — Bar charts: how many more?","body":"Which ride won the vote — and by how many?","cta":"Find out how","level":2,"route":"#/stop/bar-compare"},"idea-bar-compare-case2":{"id":"idea-bar-compare-case2","kind":"idea","src":"stop:bar-compare#case2","title":"Bar charts: how many more?: Each line is 10","body":"The lines go up in tens. A bar that stops halfway between two lines is worth a 5 in the middle.","cta":"See it worked","level":2,"route":"#/stop/bar-compare"},"algebra-bar-compare-alg":{"id":"algebra-bar-compare-alg","kind":"algebra","src":"stop:bar-compare#alg","title":"The algebra behind “Bar charts: how many more?”","body":"how many more = taller bar − shorter bar","cta":"See why","level":2,"route":"#/stop/bar-compare"},"hook-chance-words-hook":{"id":"hook-chance-words-hook","kind":"hook","src":"stop:chance-words#hook","title":"Can you? — The words of chance","body":"A bag of 3 yellow and 5 blue. Will you pick blue? Maybe — but how likely?","cta":"Find out how","level":2,"route":"#/stop/chance-words"},"worked-chance-words-worked0":{"id":"worked-chance-words-worked0","kind":"worked","src":"stop:chance-words#worked0","title":"Worked out — The words of chance: Impossible","body":"A bag holds 3 blue and 2 yellow counters. You pick one without looking. Getting green is…: How many green counters? → 0 · How many counters altogether? → 5 · 0 out of 5, so it is… → impossible","cta":"Watch it step by step","level":2,"route":"#/stop/chance-words"},"worked-chance-words-worked1":{"id":"worked-chance-words-worked1","kind":"worked","src":"stop:chance-words#worked1","title":"Worked out — The words of chance: Unlikely","body":"A bag holds 2 blue and 4 yellow counters. You pick one without looking. Getting blue is…: How many blue counters? → 2 · How many counters altogether? → 6 · 2 out of 6, so it is… → unlikely","cta":"Watch it step by step","level":2,"route":"#/stop/chance-words"},"worked-chance-words-worked3":{"id":"worked-chance-words-worked3","kind":"worked","src":"stop:chance-words#worked3","title":"Worked out — The words of chance: Likely","body":"A bag holds 5 blue and 3 yellow counters. You pick one without looking. Getting blue is…: How many blue counters? → 5 · How many counters altogether? → 8 · 5 out of 8, so it is… → likely","cta":"Watch it step by step","level":2,"route":"#/stop/chance-words"},"worked-chance-words-worked4":{"id":"worked-chance-words-worked4","kind":"worked","src":"stop:chance-words#worked4","title":"Worked out — The words of chance: Certain","body":"Roll a dice. Getting a number less than 7 is…: How many faces give a number less than 7? → 6 · How many faces altogether? → 6 · 6 out of 6, so it is… → certain","cta":"Watch it step by step","level":2,"route":"#/stop/chance-words"},"why-chance-words-why2":{"id":"why-chance-words-why2","kind":"why","src":"stop:chance-words#why2","title":"Why “The words of chance” works","body":"Anything between: fewer than half is unlikely (it can happen, it just usually won't), more than half is likely. Counting the ways is the whole trick.","cta":"See why","level":2,"route":"#/stop/chance-words"},"moment-chance-words-beat2":{"id":"moment-chance-words-beat2","kind":"moment","src":"story:chance-words#beat2","badge":{"id":"story","label":"A story"},"title":"The lucky dip — on the notepad","body":"Suki: Certain would mean every ball is blue. How many balls are there altogether? 3 + 5 = 8","cta":"Read the story","level":2,"route":"#/stop/chance-words"},"try-chance-words-L2":{"id":"try-chance-words-L2","kind":"try","level":2,"src":"try:chance-words@2/2#0","title":"The words of chance — your turn","route":"#/stop/chance-words","cta":"Practise this stop","play":{"q":"Roll a dice. Getting more than 2 is…","opts":["likely","unlikely","even chance"],"after":"Count the ways it can happen out of all the ways: none is impossible, all is certain, half is an even chance."}},"word-change":{"id":"word-change","kind":"word","src":"dictionary:change#def","title":"change","body":"The money given back when you pay more than the price. For example: Pay £5 for something costing £3.40: £1.60 back.","route":"#/lib/dictionary","cta":"Open the Dictionary","level":2},"wordq-change":{"id":"wordq-change","kind":"wordq","src":"dictionary:change#ex","title":"Which maths word?","route":"#/lib/dictionary","cta":"Open the Dictionary","play":{"q":"Which word is this an example of? “Pay £5 for something costing £3.40: £1.60 back.”","opts":["change","hexagon","mode"],"after":"change: The money given back when you pay more than the price."},"level":2},"word-column-method":{"id":"word-column-method","kind":"word","src":"dictionary:column method#def","title":"column method","body":"Writing numbers one under another, lined up by place value, and working one digit at a time. For example: 347 + 285: ones 12, tens 13, hundreds 6 → 632.","route":"#/lib/dictionary","cta":"Open the Dictionary","level":2},"wordq-column-method":{"id":"wordq-column-method","kind":"wordq","src":"dictionary:column method#ex","title":"Which maths word?","route":"#/lib/dictionary","cta":"Open the Dictionary","play":{"q":"Which word is this an example of? “347 + 285: ones 12, tens 13, hundreds 6 → 632.”","opts":["column method","nth term","hexagon"],"after":"column method: Writing numbers one under another, lined up by place value, and working one digit at a time."},"level":2},"word-estimate":{"id":"word-estimate","kind":"word","src":"dictionary:estimate#def","title":"estimate","body":"Make a sensible guess, often with easier numbers, to see roughly what an answer should be. For example: 49 × 21 is about 50 × 20 = 1,000.","route":"#/lib/dictionary","cta":"Open the Dictionary","level":2},"wordq-estimate":{"id":"wordq-estimate","kind":"wordq","src":"dictionary:estimate#ex","title":"Which maths word?","route":"#/lib/dictionary","cta":"Open the Dictionary","play":{"q":"Which word is this an example of? “49 × 21 is about 50 × 20 = 1,000.”","opts":["estimate","simple interest","commutative"],"after":"estimate: Make a sensible guess, often with easier numbers, to see roughly what an answer should be."},"level":2},"word-exchange":{"id":"word-exchange","kind":"word","src":"dictionary:exchange#def","title":"exchange","body":"Swap one from the next column on the left for ten in this one, so you can take away. Some people say “borrow”. For example: In 52 − 17 one ten becomes ten ones: 12 − 7 = 5.","route":"#/lib/dictionary","cta":"Open the Dictionary","level":2},"wordq-exchange":{"id":"wordq-exchange","kind":"wordq","src":"dictionary:exchange#ex","title":"Which maths word?","route":"#/lib/dictionary","cta":"Open the Dictionary","play":{"q":"Which word is this an example of? “In 52 − 17 one ten becomes ten ones: 12 − 7 = 5.”","opts":["exchange","data","angles on a line"],"after":"exchange: Swap one from the next column on the left for ten in this one, so you can take away. Some people say “borrow”."},"level":2},"word-halve":{"id":"word-halve","kind":"word","src":"dictionary:halve#def","title":"halve","body":"Divide by 2, or split into two equal parts. For example: 14 → 7.","route":"#/lib/dictionary","cta":"Open the Dictionary","level":2},"word-million":{"id":"word-million","kind":"word","src":"dictionary:million#def","title":"million","body":"A thousand thousands: 1,000,000. For example: 2,500,000 is two and a half of them.","route":"#/lib/dictionary","cta":"Open the Dictionary","level":2},"wordq-million":{"id":"wordq-million","kind":"wordq","src":"dictionary:million#ex","title":"Which maths word?","route":"#/lib/dictionary","cta":"Open the Dictionary","play":{"q":"Which word is this an example of? “2,500,000 is two and a half of them.”","opts":["million","net","remainder"],"after":"million: A thousand thousands: 1,000,000."},"level":2},"word-multiplication":{"id":"word-multiplication","kind":"word","src":"dictionary:multiplication#def","title":"multiplication","body":"Adding equal groups in one go. Sign: ×. For example: 4 × 3 means four groups of three: 12.","route":"#/lib/dictionary","cta":"Open the Dictionary","level":2},"wordq-multiplication":{"id":"wordq-multiplication","kind":"wordq","src":"dictionary:multiplication#ex","title":"Which maths word?","route":"#/lib/dictionary","cta":"Open the Dictionary","play":{"q":"Which word is this an example of? “4 × 3 means four groups of three: 12.”","opts":["multiplication","cubic centimetre","even"],"after":"multiplication: Adding equal groups in one go. Sign: ×."},"level":2},"word-numerator":{"id":"word-numerator","kind":"word","src":"dictionary:numerator#def","title":"numerator","body":"The top number of a fraction: how many of the equal parts you have. For example: In 3/4 it is 3.","route":"#/lib/dictionary","cta":"Open the Dictionary","level":2},"word-pentagon":{"id":"word-pentagon","kind":"word","src":"dictionary:pentagon#def","title":"pentagon","body":"A flat shape with five straight sides. For example: Its inside angles add up to 540°.","route":"#/lib/dictionary","cta":"Open the Dictionary","level":2},"wordq-pentagon":{"id":"wordq-pentagon","kind":"wordq","src":"dictionary:pentagon#ex","title":"Which maths word?","route":"#/lib/dictionary","cta":"Open the Dictionary","play":{"q":"Which word is this an example of? “Its inside angles add up to 540°.”","opts":["pentagon","formula","probability"],"after":"pentagon: A flat shape with five straight sides."},"level":2},"word-pie-chart":{"id":"word-pie-chart","kind":"word","src":"dictionary:pie chart#def","title":"pie chart","body":"A circle cut into slices to show how a whole is shared out. For example: Half the circle, 180°, for “walk to school”.","route":"#/lib/dictionary","cta":"Open the Dictionary","level":2},"wordq-pie-chart":{"id":"wordq-pie-chart","kind":"wordq","src":"dictionary:pie chart#ex","title":"Which maths word?","route":"#/lib/dictionary","cta":"Open the Dictionary","play":{"q":"Which word is this an example of? “Half the circle, 180°, for “walk to school”.”","opts":["pie chart","perpendicular height","identity"],"after":"pie chart: A circle cut into slices to show how a whole is shared out."},"level":2},"word-polygon":{"id":"word-polygon","kind":"word","src":"dictionary:polygon#def","title":"polygon","body":"A flat, closed shape made only of straight sides. For example: A triangle (3 sides) or a hexagon (6 sides).","route":"#/lib/dictionary","cta":"Open the Dictionary","level":2},"wordq-polygon":{"id":"wordq-polygon","kind":"wordq","src":"dictionary:polygon#ex","title":"Which maths word?","route":"#/lib/dictionary","cta":"Open the Dictionary","play":{"q":"Which word is this an example of? “A triangle (3 sides) or a hexagon (6 sides).”","opts":["polygon","unlikely","even"],"after":"polygon: A flat, closed shape made only of straight sides."},"level":2},"word-reflection":{"id":"word-reflection","kind":"word","src":"dictionary:reflection#def","title":"reflection","body":"Flipping a shape over a mirror line. For example: Over the y-axis, (3, 2) lands on (−3, 2).","route":"#/lib/dictionary","cta":"Open the Dictionary","level":2},"wordq-reflection":{"id":"wordq-reflection","kind":"wordq","src":"dictionary:reflection#ex","title":"Which maths word?","route":"#/lib/dictionary","cta":"Open the Dictionary","play":{"q":"Which word is this an example of? “Over the y-axis, (3, 2) lands on (−3, 2).”","opts":["reflection","union","negative number"],"after":"reflection: Flipping a shape over a mirror line."},"level":2},"word-rounding":{"id":"word-rounding","kind":"word","src":"dictionary:rounding#def","title":"rounding","body":"Swapping a number for a nearby, simpler one — to the nearest 10, 100 or whole one. For example: 347 to the nearest 10 is 350.","route":"#/lib/dictionary","cta":"Open the Dictionary","level":2},"wordq-rounding":{"id":"wordq-rounding","kind":"wordq","src":"dictionary:rounding#ex","title":"Which maths word?","route":"#/lib/dictionary","cta":"Open the Dictionary","play":{"q":"Which word is this an example of? “347 to the nearest 10 is 350.”","opts":["rounding","radius","analogue clock"],"after":"rounding: Swapping a number for a nearby, simpler one — to the nearest 10, 100 or whole one."},"level":2},"word-sum":{"id":"word-sum","kind":"word","src":"dictionary:sum#def","title":"sum","body":"The answer when numbers are added together. People also use it for any calculation. For example: For 8 and 5 it is 13.","route":"#/lib/dictionary","cta":"Open the Dictionary","level":2},"word-times-table":{"id":"word-times-table","kind":"word","src":"dictionary:times table#def","title":"times table","body":"The list of a number multiplied by 1, 2, 3 and so on, usually up to 12. For example: The 7s: 7, 14, 21, 28, 35, …","route":"#/lib/dictionary","cta":"Open the Dictionary","level":2},"wordq-times-table":{"id":"wordq-times-table","kind":"wordq","src":"dictionary:times table#ex","title":"Which maths word?","route":"#/lib/dictionary","cta":"Open the Dictionary","play":{"q":"Which word is this an example of? “The 7s: 7, 14, 21, 28, 35, …”","opts":["times table","average","digit root"],"after":"times table: The list of a number multiplied by 1, 2, 3 and so on, usually up to 12."},"level":2},"word-whole-number":{"id":"word-whole-number","kind":"word","src":"dictionary:whole number#def","title":"whole number","body":"One of 0, 1, 2, 3 and so on, with no fraction or decimal part. For example: 14 is one; 14.5 is not.","route":"#/lib/dictionary","cta":"Open the Dictionary","level":2},"wordq-whole-number":{"id":"wordq-whole-number","kind":"wordq","src":"dictionary:whole number#ex","title":"Which maths word?","route":"#/lib/dictionary","cta":"Open the Dictionary","play":{"q":"Which word is this an example of? “14 is one; 14.5 is not.”","opts":["whole number","decimal point","right-angled triangle"],"after":"whole number: One of 0, 1, 2, 3 and so on, with no fraction or decimal part."},"level":2},"formula-fraction-of-amount":{"id":"formula-fraction-of-amount","kind":"formula","src":"formula:fraction-of-amount","title":"A fraction of an amount","body":"a/b of n = n ÷ b × a. Cut into b equal parts, then take a of them.","route":"#/lib/formulas","cta":"Open the Formula Book","play":{"q":"A fraction of an amount: 3/4 of 20.","opts":["15","16","14"],"after":"20 ÷ 4 = 5 · 5 × 3 = 15"},"level":2},"formula-why-fraction-of-amount-0":{"id":"formula-why-fraction-of-amount-0","kind":"formula-why","src":"formula:fraction-of-amount#why0","title":"Why a/b of n = n ÷ b × a","body":"The bottom number says how many equal parts to cut n into, so n ÷ b is the size of one part.","route":"#/lib/formulas","cta":"Open the Formula Book","level":2},"formula-why-fraction-of-amount-1":{"id":"formula-why-fraction-of-amount-1","kind":"formula-why","src":"formula:fraction-of-amount#why1","title":"Why a/b of n = n ÷ b × a","body":"The top number says how many of those parts you take, so multiply by a. 3/4 of 20: one quarter is 20 ÷ 4 = 5, and three quarters is 3 × 5 = 15.","route":"#/lib/formulas","cta":"Open the Formula Book","level":2},"formula-story-fraction-of-amount":{"id":"formula-story-fraction-of-amount","kind":"formula-story","src":"formula:fraction-of-amount#story","badge":{"id":"story","label":"A story"},"title":"The school trip","body":"There are 32 seats on the school bus and 3/4 of them are full. How many children are on board? — with Nova and Pip.","art":"art/s-bus.webp","route":"#/lib/formulas","cta":"Open the Formula Book","level":2},"formula-try-fraction-of-amount":{"id":"formula-try-fraction-of-amount","kind":"formula-try","src":"formula:fraction-of-amount#gen0","title":"A fraction of an amount — your turn","route":"#/lib/formulas","cta":"Open the Formula Book","play":{"q":"1/2 of 22 = ?","opts":["11","12","10"],"after":"a/b of n = n ÷ b × a"},"level":2}};
